const joy = document.getElementById('joystick'), knob = ...;
const joyState = {id:null};
let touchInput = {x:0, y:0};
function joyStart(e){ e.preventDefault(); if(joyState.id!==null) return; joyState.id=e.pointerId; joy.setPointerCapture(e.pointerId); joyMove(e); }
function joyMove(e){ if(e.pointerId!==joyState.id) return; const r=joy.getBoundingClientRect(); const cx=r.left+r.width/2, cy=r.top+r.height/2; let dx=e.clientX-cx, dy=e.clientY-cy; const max=r.width*0.34; const len=Math.hypot(dx,dy)||1; if(len>max){ dx=dx/len*max; dy=dy/len*max; } knob.style.transform=`translate(${dx}px, ${dy}px)`; touchInput.x = dx/max; touchInput.y = -dy/max; }
function joyEnd(e){ if(e.pointerId!==joyState.id) return; joyState.id=null; touchInput.x=0; touchInput.y=0; knob.style.transform=''; }
