+            z + (Math.random() - 0.5) * 0.55
+        );
+        p.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
+        p.userData.vel = new THREE.Vector3(
+            (Math.random() - 0.5) * 3.4,
+            1.4 + Math.random() * 2.8,
+            (Math.random() - 0.5) * 3.4
+        );
+        p.userData.spin = new THREE.Vector3(
+            (Math.random() - 0.5) * 8,
+            (Math.random() - 0.5) * 8,
+            (Math.random() - 0.5) * 8
+        );
+        p.userData.life = 0.42 + Math.random() * 0.38;
+        p.userData.maxLife = p.userData.life;
+        scene.add(p);
+        particles.push(p);
+    }
+}
+
+function updateParticles(dt) {
+    for (let i = particles.length - 1; i >= 0; i--) {
+        const p = particles[i];
+        const u = p.userData;
+        u.life -= dt;
+        if (u.life <= 0) {
+            scene.remove(p);
+            particles.splice(i, 1);
+            continue;
+        }
+        u.vel.y -= 20 * dt;
+        p.position.addScaledVector(u.vel, dt);
+        p.rotation.x += u.spin.x * dt;
+        p.rotation.y += u.spin.y * dt;
+        p.rotation.z += u.spin.z * dt;
+        const s = clamp(u.life / u.maxLife, 0, 1);
+        p.scale.setScalar(0.35 + s * 0.75);
+    }
+}
+
+/*@@GAME3@@*/
     </script>
 </body>
 </html>

