/* ---------------- Arayüz durumu ---------------- */
const overlay = document.getElementById('overlay');
const startBtn = document.getElementById('startBtn');
const resetBtn = document.getElementById('resetBtn');
const eyebrow = overlay.querySelector('.eyebrow');
const toastEl = document.getElementById('toast');
const slotEls = Array.from(document.querySelectorAll('.slot'));
const btnBreak = document.getElementById('btnBreak');
const btnPlace = document.getElementById('btnPlace');
const btnJump = document.getElementById('btnJump');
const joystick = document.getElementById('joystick');
const knob = document.getElementById('knob');

let playing = false;
let locked = false;
let started = false;
let selectedType = 1;
let startEyebrow = '3D Voxel Sandbox';
let toastTimer = 0;

function toast(message) {
    toastEl.textContent = message;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toastEl.classList.remove('show'), 1600);
}

/* ---------------- Ses ---------------- */
let audioCtx = null;
let muted = false;

function initAudio() {
    if (!audioCtx) {
        try {
            const AC = window.AudioContext || window.webkitAudioContext;
            if (AC) audioCtx = new AC();
        } catch (error) {
            audioCtx = null;
        }
    }
    if (audioCtx && audioCtx.state === 'suspended') {
        audioCtx.resume().catch(() => {});
    }
}

function tone(f0, f1, dur, type, vol) {
    if (!audioCtx || muted || audioCtx.state !== 'running') return;
    const t = audioCtx.currentTime;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(f0, t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(25, f1), t + dur);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(vol, t + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start(t);
    osc.stop(t + dur + 0.03);
}

function sfx(kind) {
    switch (kind) {
        case 'break': tone(190, 70, 0.13, 'square', 0.032); break;
        case 'place': tone(135, 225, 0.085, 'sine', 0.05); break;
        case 'jump': tone(300, 440, 0.11, 'sine', 0.024); break;
        case 'select': tone(520, 640, 0.05, 'sine', 0.018); break;
        case 'deny': tone(120, 80, 0.1, 'sawtooth', 0.022); break;
    }
}

function toggleMute() {
    muted = !muted;
    if (!muted) { initAudio(); sfx('select'); }
    toast(muted ? 'Ses kapatıldı' : 'Ses açıldı');
}

/* ---------------- Blok seçimi ---------------- */
function selectSlot(index) {
    if (index < 0 || index > 7) return;
    selectedType = index + 1;
    slotEls.forEach((el, i) => {
        el.classList.toggle('active', i === index);
        el.setAttribute('aria-pressed', i === index ? 'true' : 'false');
    });
    sfx('select');
}

slotEls.forEach((el, i) => {
    el.addEventListener('click', (event) => {
        event.preventDefault();
        selectSlot(i);
    });
});

/* ---------------- Oyun akışı ---------------- */
function beginPlay() {
    started = true;
    overlay.classList.add('hidden');
    overlay.classList.remove('paused');
    eyebrow.textContent = startEyebrow;
    initAudio();

    if (isCoarse) {
        playing = true;
        document.body.classList.add('playing');
        return;
    }

    if (!locked && renderer.domElement.requestPointerLock) {
        try {
            const result = renderer.domElement.requestPointerLock();
            if (result && result.catch) result.catch(() => {});
        } catch (error) { /* tarayıcı kilidi reddetti */ }
    }
}

function showPause() {
    overlay.classList.remove('hidden');
    overlay.classList.add('paused');
    eyebrow.textContent = 'Oyun duraklatıldı';
    startBtn.textContent = 'Devam Et';
}

function resetWorld() {
    clearWorld();
    particles.forEach((p) => scene.remove(p));
    particles.length = 0;
    generateWorld();
    respawn(false);
    toast('Dünya yenilendi 🌍');
    sfx('place');
}

startBtn.addEventListener('click', (event) => {
    event.stopPropagation();
    beginPlay();
});
overlay.addEventListener('click', (event) => {
    if (event.target.closest('button')) return;
    beginPlay();
});
resetBtn.addEventListener('click', (event) => {
    event.stopPropagation();
    resetWorld();
    beginPlay();
});

/* ---------------- Fare kilidi ---------------- */
document.addEventListener('pointerlockchange', () => {
    const nowLocked = document.pointerLockElement === renderer.domElement;
    if (nowLocked) {
        locked = true;
        playing = true;
        started = true;
        overlay.classList.add('hidden');
        document.body.classList.add('playing');
    } else {
        const wasLocked = locked;
        locked = false;
        if (wasLocked && !isCoarse) {
            playing = false;
            keys.clear();
            wantJump = false;
            touchInput.x = 0;
            touchInput.y = 0;
            document.body.classList.remove('playing');
            showPause();
        }
    }
});

document.addEventListener('pointerlockerror', () => {
    toast('Fare kilidi açılamadı. Sahneye tıklayıp tekrar dene.');
});

document.addEventListener('mousemove', (event) => {
    if (!locked || !playing) return;
    yaw -= event.movementX * 0.0022;
    pitch = clamp(pitch - event.movementY * 0.0022, -1.45, 1.45);
});

renderer.domElement.addEventListener('pointerdown', (event) => {
    if (isCoarse) return;
    if (!locked && started) beginPlay();
});

document.addEventListener('mousedown', (event) => {
    if (isCoarse || !locked || !playing) return;
    if (event.button === 0) breakTarget();
    else if (event.button === 2) placeBlock();
});

document.addEventListener('contextmenu', (event) => event.preventDefault());

/* ---------------- Klavye ---------------- */
window.addEventListener('keydown', (event) => {
    if (event.code === 'KeyM' && !event.repeat) {
        toggleMute();
        return;
    }
    if (!playing) return;

    if (event.code === 'Space') {
        event.preventDefault();
        if (!event.repeat) wantJump = true;
        return;
    }
    if (event.code === 'KeyW' || event.code === 'KeyA' ||
        event.code === 'KeyS' || event.code === 'KeyD') {
        keys.add(event.code);
        return;
    }
    if (event.code.indexOf('Digit') === 0) {
        const n = Number(event.code.slice(5));
        if (n >= 1 && n <= 8) selectSlot(n - 1);
        return;
    }
    if (event.code === 'KeyR' && !event.repeat) {
        resetWorld();
    }
});

window.addEventListener('keyup', (event) => {
    keys.delete(event.code);
});

window.addEventListener('blur', () => {
    keys.clear();
    wantJump = false;
});

document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
        keys.clear();
        wantJump = false;
    }
});

/* ---------------- Dokunmatik kontroller ---------------- */
let lookPointer = null;
let lookX = 0;
let lookY = 0;

renderer.domElement.addEventListener('pointerdown', (event) => {
    if (!isCoarse || !playing) return;
    if (event.pointerType !== 'touch' && event.pointerType !== 'pen') return;
    if (lookPointer !== null) return;
    lookPointer = event.pointerId;
    lookX = event.clientX;
    lookY = event.clientY;
    try { renderer.domElement.setPointerCapture(event.pointerId); } catch (error) {}
});

renderer.domElement.addEventListener('pointermove', (event) => {
    if (!isCoarse || !playing || event.pointerId !== lookPointer) return;
    const dx = event.clientX - lookX;
    const dy = event.clientY - lookY;
    lookX = event.clientX;
    lookY = event.clientY;
    yaw -= dx * 0.0052;
    pitch = clamp(pitch - dy * 0.0052, -1.45, 1.45);
});

function endLook(event) {
    if (event.pointerId === lookPointer) lookPointer = null;
}
renderer.domElement.addEventListener('pointerup', endLook);
renderer.domElement.addEventListener('pointercancel', endLook);

let joyPointer = null;

function joyMove(event) {
    const rect = joystick.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const max = rect.width * 0.34;
    let dx = event.clientX - cx;
    let dy = event.clientY - cy;
    const len = Math.hypot(dx, dy);
    if (len > max) {
        dx = dx / len * max;
        dy = dy / len * max;
    }
    knob.style.transform = 'translate(' + dx + 'px, ' + dy + 'px)';
    touchInput.x = dx / max;
    touchInput.y = -dy / max;
}

joystick.addEventListener('pointerdown', (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (joyPointer !== null) return;
    joyPointer = event.pointerId;
    try { joystick.setPointerCapture(event.pointerId); } catch (error) {}
    joyMove(event);
});
joystick.addEventListener('pointermove', (event) => {
    if (event.pointerId !== joyPointer) return;
    event.preventDefault();
    joyMove(event);
});

function endJoy(event) {
    if (event.pointerId !== joyPointer) return;
    joyPointer = null;
    touchInput.x = 0;
    touchInput.y = 0;
    knob.style.transform = 'translate(0, 0)';
}
joystick.addEventListener('pointerup', endJoy);
joystick.addEventListener('pointercancel', endJoy);
joystick.addEventListener('lostpointercapture', endJoy);

function bindTouchButton(el, action) {
    el.addEventListener('pointerdown', (event) => {
        event.preventDefault();
        event.stopPropagation();
        el.classList.add('pressed');
        action();
    });
    const release = () => el.classList.remove('pressed');
    el.addEventListener('pointerup', release);
    el.addEventListener('pointercancel', release);
    el.addEventListener('pointerleave', release);
}
bindTouchButton(btnJump, () => { wantJump = true; });
bindTouchButton(btnBreak, breakTarget);
bindTouchButton(btnPlace, placeBlock);

/* ---------------- Blok kırma / koyma ---------------- */
function breakTarget() {
    const hit = currentTarget;
    if (!hit) return;
    const u = hit.object.userData;
    if (u.y <= 0) {
        toast('Ana kaya kırılamaz 🪨');
        sfx('deny');
        return;
    }
    removeBlockAt(u.x, u.y, u.z);
    burst(u.x + 0.5, u.y + 0.5, u.z + 0.5, u.type);
    currentTarget = null;
    highlight.visible = false;
    sfx('break');
}

function placeBlock() {
    const hit = currentTarget;
    if (!hit || !hit.face) return;
    const u = hit.object.userData;
    const n = hit.face.normal;
    const x = u.x + Math.round(n.x);
    const y = u.y + Math.round(n.y);
    const z = u.z + Math.round(n.z);

    if (blockMap.has(keyOf(x, y, z))) return;
    if (y < 0 || y > 48) {
        toast('Daha yükseğe koyamazsın');
        return;
    }
    if (blockHitsPlayer(x, y, z)) {
        toast('Buraya sığmıyor 🙃');
        sfx('deny');
        return;
    }
    addBlock(x, y, z, selectedType, true);
    sfx('place');
}

/* ---------------- Pencere ---------------- */
function onResize() {
    camera.aspect = innerWidth / innerHeight;
    camera.updateProjectionMatrix();
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(innerWidth, innerHeight);
}
window.addEventListener('resize', onResize);
window.addEventListener('orientationchange', () => setTimeout(onResize, 150));

/* ---------------- Ana döngü ---------------- */
let lastTime = performance.now();
let elapsed = 0;
let bobPhase = 0;

function updateGrow(dt) {
    for (let i = growQueue.length - 1; i >= 0; i--) {
        const mesh = growQueue[i];
        const s = Math.min(1, mesh.scale.x + dt * 5.5);
        mesh.scale.setScalar(s);
        if (s >= 1) growQueue.splice(i, 1);
    }
}

function animate() {
    requestAnimationFrame(animate);
    const now = performance.now();
    let dt = (now - lastTime) / 1000;
    lastTime = now;
    if (dt > 0.1) dt = 0.1;
    elapsed += dt;

    if (playing) updatePlayer(dt);

    const speed = Math.hypot(player.vel.x, player.vel.z);
    if (playing && player.grounded && speed > 0.35) {
        bobPhase += dt * (6 + speed * 1.15);
    }
    const bob = (playing && player.grounded)
        ? Math.sin(bobPhase) * Math.min(speed * 0.006, 0.032)
        : 0;

    camera.position.set(player.pos.x, player.pos.y + EYE + bob, player.pos.z);
    camera.rotation.x = pitch;
    camera.rotation.y = yaw;
    camera.rotation.z = 0;

    updateTarget();
    updateParticles(dt);
    updateGrow(dt);

    for (const cloud of clouds) {
        cloud.group.position.x += cloud.speed * dt;
        if (cloud.group.position.x > 78) cloud.group.position.x = -78;
    }
    water.position.y = 2.15 + Math.sin(elapsed * 0.7) * 0.012;
    water.material.opacity = 0.8 + Math.sin(elapsed * 0.9) * 0.025;

    renderer.render(scene, camera);
}

respawn(false);
animate();

