const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = require(join(runtime, 'node_modules/playwright'));
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = process.argv[2] || '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

(async () => {
  const browser = await chromium.launch(config.browser.launchOptions);
  const errors = [];

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  desktop.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  desktop.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await desktop.goto('http://localhost:3000', { waitUntil: 'load' });
  await desktop.waitForTimeout(900);
  await desktop.screenshot({ path: join(out, '01-menu.jpg'), type: 'jpeg', quality: 82 });
  await desktop.locator('#startBtn').click();
  await desktop.waitForTimeout(1600);
  const state = await desktop.evaluate(() => ({
    playing: typeof playing === 'undefined' ? 'missing' : playing,
    locked: typeof locked === 'undefined' ? 'missing' : locked,
    blocks: typeof blocks === 'undefined' ? -1 : blocks.length,
    overlayHidden: document.getElementById('overlay').classList.contains('hidden'),
    canvas: !!document.querySelector('canvas'),
    pos: typeof player === 'undefined' ? null : player.pos.toArray().map(n => +n.toFixed(2)),
    cam: typeof camera === 'undefined' ? null : camera.position.toArray().map(n => +n.toFixed(2))
  }));
  console.log('DESKTOP_STATE', JSON.stringify(state));
  await desktop.screenshot({ path: join(out, '02-game.jpg'), type: 'jpeg', quality: 82 });

  // Look down a bit and try breaking the block under the crosshair.
  const action = await desktop.evaluate(() => {
    if (typeof pitch === 'number') pitch = -0.85;
    return { before: blocks.length };
  });
  await desktop.waitForTimeout(400);
  await desktop.evaluate(() => { if (typeof breakTarget === 'function') breakTarget(); });
  await desktop.waitForTimeout(500);
  const after = await desktop.evaluate(() => ({ blocks: blocks.length, target: !!currentTarget }));
  console.log('BREAK_TEST', JSON.stringify(action), JSON.stringify(after));
  await desktop.screenshot({ path: join(out, '03-break.jpg'), type: 'jpeg', quality: 82 });

  // Reset world via key path, then place at the aimed face.
  await desktop.evaluate(() => { if (typeof resetWorld === 'function') resetWorld(); pitch = -0.65; });
  await desktop.waitForTimeout(300);
  await desktop.evaluate(() => { if (typeof placeBlock === 'function') placeBlock(); });
  await desktop.waitForTimeout(500);
  const placed = await desktop.evaluate(() => ({ blocks: blocks.length, selected: selectedType }));
  console.log('PLACE_TEST', JSON.stringify(placed));

  // Mobile emulation
  const mobileCtx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
  const mobile = await mobileCtx.newPage();
  mobile.on('pageerror', e => errors.push('MOBILE PAGEERROR ' + e.message));
  mobile.on('console', m => { if (m.type() === 'error') errors.push('MOBILE CONSOLE ' + m.text()); });
  await mobile.goto('http://localhost:3000', { waitUntil: 'load' });
  await mobile.waitForTimeout(900);
  await mobile.locator('#startBtn').click();
  await mobile.waitForTimeout(1400);
  const mobileState = await mobile.evaluate(() => ({
    touchClass: document.body.classList.contains('touch'),
    playing: typeof playing === 'undefined' ? 'missing' : playing,
    touchUi: getComputedStyle(document.getElementById('touch-ui')).display,
    hotbarBottom: getComputedStyle(document.getElementById('hotbar')).bottom,
    overlayHidden: document.getElementById('overlay').classList.contains('hidden')
  }));
  console.log('MOBILE_STATE', JSON.stringify(mobileState));
  await mobile.screenshot({ path: join(out, '04-mobile.jpg'), type: 'jpeg', quality: 82 });

  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

