input.content:
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = require(join(runtime, 'node_modules/playwright'));
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = process.argv[2] || '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

(async () => {
  const browser = await chromium.launch(config.browser.launchOptions);
  const errors = [];

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  desktop.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  desktop.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await desktop.goto('http://localhost:3000', { waitUntil: 'load' });
  await desktop.waitForTimeout(900);
  await desktop.screenshot({ path: join(out, '01-menu.jpg'), type: 'jpeg', quality: 82 });
  await desktop.locator('#startBtn').click();
  await desktop.waitForTimeout(1400);
  const state = await desktop.evaluate(() => ({
    playing, locked, blocks: blocks.length,
    overlayHidden: document.getElementById('overlay').classList.contains('hidden'),
    touchClass: document.body.classList.contains('touch'),
    pos: player.pos.toArray().map(n => +n.toFixed(2)),
    cam: camera.position.toArray().map(n => +n.toFixed(2)),
    yaw: +yaw.toFixed(3), pitch: +pitch.toFixed(3), grounded: player.grounded
  }));
  console.log('DESKTOP_STATE', JSON.stringify(state));
  await desktop.screenshot({ path: join(out, '02-game.jpg'), type: 'jpeg', quality: 82 });

  await desktop.keyboard.down('w');
  await desktop.waitForTimeout(650);
  await desktop.keyboard.up('w');
  const moved = await desktop.evaluate(() => player.pos.toArray().map(n => +n.toFixed(2)));
  await desktop.mouse.move(700, 380);
  await desktop.mouse.move(820, 330);
  await desktop.waitForTimeout(250);
  const looked = await desktop.evaluate(() => ({ playing, locked, yaw: +yaw.toFixed(3), pitch: +pitch.toFixed(3) }));
  await desktop.keyboard.press('Space');
  await desktop.waitForTimeout(170);
  const jumped = await desktop.evaluate(() => ({ y: +player.pos.y.toFixed(2), vy: +player.vel.y.toFixed(2), grounded: player.grounded, playing, locked }));
  console.log('MOVE', JSON.stringify(moved), 'LOOK', JSON.stringify(looked), 'JUMP', JSON.stringify(jumped));

  await desktop.evaluate(() => { pitch = -0.85; });
  await desktop.waitForTimeout(350);
  const breakTest = await desktop.evaluate(() => {
    const before = blocks.length, hadTarget = !!currentTarget;
    breakTarget();
    return { before, after: blocks.length, hadTarget };
  });
  await desktop.waitForTimeout(400);
  await desktop.screenshot({ path: join(out, '03-break.jpg'), type: 'jpeg', quality: 82 });
  await desktop.evaluate(() => { resetWorld(); pitch = -0.75; });
  await desktop.waitForTimeout(400);
  const placeTest = await desktop.evaluate(() => {
    const before = blocks.length, hadTarget = !!currentTarget;
    placeBlock();
    const mid = blocks.length;
    placeBlock();
    return { before, mid, after: blocks.length, hadTarget, selected: selectedType };
  });
  console.log('BREAK', JSON.stringify(breakTest), 'PLACE', JSON.stringify(placeTest));

  // Mobile portrait
  const mobileCtx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
  const mobile = await mobileCtx.newPage();
  await mobile.bringToFront();
  mobile.on('pageerror', e => errors.push('MOBILE PAGEERROR ' + e.message));
  mobile.on('console', m => { if (m.type() === 'error') errors.push('MOBILE CONSOLE ' + m.text()); });
  await mobile.goto('http://localhost:3000', { waitUntil: 'load' });
  await mobile.waitForTimeout(700);
  await mobile.screenshot({ path: join(out, '04-mobile-menu.jpg'), type: 'jpeg', quality: 82 });
  await mobile.locator('#startBtn').click();
  await mobile.waitForTimeout(1300);
  const mobileState = await mobile.evaluate(() => {
    const rect = el => { const r = el.getBoundingClientRect(); return { x: +r.x.toFixed(0), y: +r.y.toFixed(0), w: +r.width.toFixed(0), h: +r.height.toFixed(0) }; };
    const hotbar = rect(document.getElementById('hotbar'));
    const jump = rect(document.getElementById('btnJump'));
    const overlap = !(hotbar.x + hotbar.w < jump.x || jump.x + jump.w < hotbar.x || hotbar.y + hotbar.h < jump.y || jump.y + jump.h < hotbar.y);
    return {
      touchClass: document.body.classList.contains('touch'), playing,
      touchUi: getComputedStyle(document.getElementById('touch-ui')).display,
      tools: getComputedStyle(document.getElementById('mobile-tools')).display,
      hotbar, jump, overlap, snapped: jump.y - (hotbar.y + hotbar.h),
      overlayHidden: document.getElementById('overlay').classList.contains('hidden'),
      sound: document.getElementById('soundBtn').textContent
    };
  });
  console.log('MOBILE_STATE', JSON.stringify(mobileState));
  await mobile.screenshot({ path: join(out, '05-mobile-game.jpg'), type: 'jpeg', quality: 82 });

  // Joystick drag
  const joy = await mobile.evaluate(() => {
    const el = document.getElementById('joystick');
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
    const opts = { pointerId: 7, pointerType: 'touch', bubbles: true, cancelable: true };
    el.dispatchEvent(new PointerEvent('pointerdown', { ...opts, clientX: cx, clientY: cy }));
    el.dispatchEvent(new PointerEvent('pointermove', { ...opts, clientX: cx + 20, clientY: cy - 36 }));
    return { x: +touchInput.x.toFixed(2), y: +touchInput.y.toFixed(2) };
  });
  await mobile.waitForTimeout(700);
  const afterJoy = await mobile.evaluate(() => {
    const el = document.getElementById('joystick');
    el.dispatchEvent(new PointerEvent('pointerup', { pointerId: 7, pointerType: 'touch', bubbles: true }));
    return { pos: player.pos.toArray().map(n => +n.toFixed(2)), input: [+touchInput.x.toFixed(2), +touchInput.y.toFixed(2)], playing };
  });
  console.log('JOYSTICK', JSON.stringify(joy), 'AFTER', JSON.stringify(afterJoy));

  // Sound toggle
  const sound = await mobile.evaluate(() => {
    const before = document.getElementById('soundBtn').textContent;
    document.getElementById('soundBtn').click();
    return { before, after: document.getElementById('soundBtn').textContent, muted };
  });
  console.log('SOUND', JSON.stringify(sound));

  // Menu button -> paused overlay -> reset -> resume
  const menu = await mobile.evaluate(() => {
    document.getElementById('menuBtn').click();
    return {
      playing, overlayHidden: document.getElementById('overlay').classList.contains('hidden'),
      paused: document.getElementById('overlay').classList.contains('paused'),
      resetVisible: getComputedStyle(document.getElementById('resetBtn')).display,
      button: document.getElementById('startBtn').textContent
    };
  });
  await mobile.waitForTimeout(300);
  await mobile.screenshot({ path: join(out, '06-mobile-pause.jpg'), type: 'jpeg', quality: 82 });
  await mobile.locator('#startBtn').click();
  await mobile.waitForTimeout(500);
  const resumed = await mobile.evaluate(() => ({ playing, overlayHidden: document.getElementById('overlay').classList.contains('hidden') }));
  console.log('MENU', JSON.stringify(menu), 'RESUMED', JSON.stringify(resumed));

  // Landscape
  const landCtx = await browser.newContext({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
  const land = await landCtx.newPage();
  await land.bringToFront();
  await land.goto('http://localhost:3000', { waitUntil: 'load' });
  await land.waitForTimeout(600);
  await land.locator('#startBtn').click();
  await land.waitForTimeout(1000);
  const landState = await land.evaluate(() => {
    const rect = el => { const r = el.getBoundingClientRect(); return { x: +r.x.toFixed(0), y: +r.y.toFixed(0), w: +r.width.toFixed(0), h: +r.height.toFixed(0) }; };
    return { touch: document.body.classList.contains('touch'), hotbar: rect(document.getElementById('hotbar')), joy: rect(document.getElementById('joystick')), jump: rect(document.getElementById('btnJump')), playing };
  });
  console.log('LANDSCAPE', JSON.stringify(landState));
  await land.screenshot({ path: join(out, '07-landscape.jpg'), type: 'jpeg', quality: 82 });

  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

