const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = require(join(runtime, 'node_modules/playwright'));
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = process.argv[2] || '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

(async () => {
  const browser = await chromium.launch(config.browser.launchOptions);
  const errors = [];

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  desktop.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  desktop.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await desktop.goto('http://localhost:3000', { waitUntil: 'load' });
  await desktop.waitForTimeout(900);
  await desktop.screenshot({ path: join(out, '01-menu.jpg'), type: 'jpeg', quality: 82 });
  await desktop.locator('#startBtn').click();
  await desktop.waitForTimeout(1400);
  const state = await desktop.evaluate(() => ({
    playing, locked, blocks: blocks.length,
    overlayHidden: document.getElementById('overlay').classList.contains('hidden'),
    touchClass: document.body.classList.contains('touch'),
    pos: player.pos.toArray().map(n => +n.toFixed(2)),
    cam: camera.position.toArray().map(n => +n.toFixed(2)),
    yaw: +yaw.toFixed(3), pitch: +pitch.toFixed(3), grounded: player.grounded
  }));
  console.log('DESKTOP_STATE', JSON.stringify(state));
  await desktop.screenshot({ path: join(out, '02-game.jpg'), type: 'jpeg', quality: 82 });

  await desktop.keyboard.down('w');
  await desktop.waitForTimeout(650);
  await desktop.keyboard.up('w');
  const moved = await desktop.evaluate(() => player.pos.toArray().map(n => +n.toFixed(2)));
  await desktop.mouse.move(700, 380);
  await desktop.mouse.move(820, 330);
  await desktop.waitForTimeout(250);
  const looked = await desktop.evaluate(() => ({ playing, locked, yaw: +yaw.toFixed(3), pitch: +pitch.toFixed(3) }));

